from matplotlib.patches import Rectangle, Circle
fig = plt.gcf(); fig.set_size_inches(6.2, 6.2)
ax = fig.add_axes([0, 0, 1, 1])
n = 10
for i in range(n + 1):
    for j in range(n + 1):
        x, y = j, n - i
        if i == 0 and j == 0:
            ax.text(x + 0.5, y + 0.5, '$\\times$', ha='center', va='center', fontsize=13)
        elif i == 0 or j == 0:
            ax.add_patch(Rectangle((x, y), 1, 1, fc=(0.88, 0.88, 0.88), ec='black', lw=0.8))
            ax.text(x + 0.5, y + 0.5, str(i + j), ha='center', va='center', fontsize=12, weight='bold')
        else:
            fc = (0.75, 0.85, 1.0) if i == j else 'none'
            ax.add_patch(Rectangle((x, y), 1, 1, fc=fc, ec='black', lw=0.6))
            ax.text(x + 0.5, y + 0.5, str(i * j), ha='center', va='center', fontsize=11)
for (i, j) in [(3, 7), (7, 3)]:
    ax.add_patch(Circle((j + 0.5, n - i + 0.5), 0.45, fc='none', ec='red', lw=2.0))
ax.set_xlim(-0.05, n + 1.05); ax.set_ylim(-0.05, n + 1.05); ax.set_aspect('equal'); ax.axis('off')
